import { useState } from "react";

export function LanternCounter() {
  const [lanterns, setLanterns] = useState(0);
  return (
    <button onClick={() => setLanterns(value => value + 1)}>
      Lanterns: {lanterns}
    </button>
  );
}

import { useMemo, useState } from "react";

export function OrchardPicker({ varieties }) {
  const [query, setQuery] = useState("");
  const visible = useMemo(
    () => varieties.filter(value => value.toLowerCase().includes(query.toLowerCase())),
    [varieties, query]
  );
  return (
    <section>
      <input value={query} onChange={event => setQuery(event.target.value)} />
      <ul>{visible.map(value => <li key={value}>{value}</li>)}</ul>
    </section>
  );
}

import sqlite3


def record_telescope_reading(database_path: str, magnitude: float) -> int:
    connection = sqlite3.connect(database_path)
    try:
        with connection:
            connection.execute(
                "CREATE TABLE IF NOT EXISTS telescope_readings "
                "(id INTEGER PRIMARY KEY, magnitude REAL NOT NULL)"
            )
            cursor = connection.execute(
                "INSERT INTO telescope_readings (magnitude) VALUES (?)",
                (magnitude,),
            )
            return int(cursor.lastrowid)
    finally:
        connection.close()

import json

from redis import Redis


atlas_store = Redis(host="localhost", port=6379, decode_responses=True)


def remember_route(route_code: str, waypoints: list[str]) -> None:
    atlas_store.set(f"atlas:{route_code}", json.dumps(waypoints), ex=120)


def recall_route(route_code: str) -> list[str] | None:
    encoded = atlas_store.get(f"atlas:{route_code}")
    return None if encoded is None else json.loads(encoded)

from decimal import Decimal, ROUND_HALF_UP


def pottery_total(prices: list[Decimal], discount: Decimal) -> Decimal:
    if not Decimal("0") <= discount <= Decimal("1"):
        raise ValueError("Discount must be between zero and one")
    subtotal = sum(prices, start=Decimal("0"))
    return (subtotal * (Decimal("1") - discount)).quantize(
        Decimal("0.01"), rounding=ROUND_HALF_UP
    )

def ridge_median(heights: list[float]) -> float:
    if not heights:
        raise ValueError("At least one height is required")
    ordered = sorted(heights)
    midpoint = len(ordered) // 2
    if len(ordered) % 2:
        return ordered[midpoint]
    return (ordered[midpoint - 1] + ordered[midpoint]) / 2

export function boundCompass(value: number, lower: number, upper: number): number {
  if (![value, lower, upper].every(Number.isFinite)) {
    throw new Error("Bounds and value must be finite");
  }
  if (lower > upper) {
    throw new Error("Lower bound exceeds upper bound");
  }
  return Math.min(upper, Math.max(lower, value));
}

export function pebbleFrequencies(values: readonly string[]): Record<string, number> {
  const counts: Record<string, number> = Object.create(null);
  for (const value of values) {
    counts[value] = (counts[value] ?? 0) + 1;
  }
  return counts;
}
